using System;
using System.Linq;
using DesktopCritters.Core;
namespace DesktopCritters;
public static class FeatureTests {
 private static World Empty(){var w=new World(1440,900,113);w.Bugs.Clear();w.Foods.Clear();w.Eggs.Clear();w.Serial=1000;w.InvasionTimer=10000;w.AutoFoodTimer=-10000;w.RoachBirth=w.AntBirth=10000;return w;}
 public static void Run(Action<bool,string> check){var w=Empty();var b=new Bug{Id=1,Species=Species.Roach,P=new V(500,400)};w.Bugs.Add(b);
  check(!w.BeginFlight(new Bug{Id=2,Species=Species.Ant,P=b.P}),"ants remain ground creatures");check(!w.BeginFlight(new Bug{Id=3,Species=Species.Roach,P=b.P,Growth=.7}),"wingless nymphs cannot fly");b.Web=2;check(!w.BeginFlight(b),"spider silk prevents takeoff");b.Web=0;w.Grabbed=1;check(!w.BeginFlight(b),"held roaches cannot take off");w.Grabbed=null;check(w.BeginFlight(b),"adult roach starts real flight");var start=b.P;check(b.Flight!.Point(0)==start&&b.Flight.Point(1)==b.Flight.End,"flight endpoints join takeoff and landing");
  w.Paused=true;w.Update(.05);check(b.P==start&&b.Flight.Elapsed==0,"pause freezes flight position and wings");check(w.ScareRoaches()==0,"manual scare respects pause");w.Paused=false;for(int n=0;n<20;n++)w.Update(.05);check(b.P.Distance(start)>20&&b.Flight.Lift>10&&b.Flight.Open>.9,"flying body moves with open wings and separated shadow");check(w.BodyHit(b,b.P),"flying hit area follows visible body");w.AddFood(b.P,Snack.Pizza);int food=w.Foods[0].Portions;b.Cooldown=0;w.Bite(b,w.Foods[0]);check(w.Foods[0].Portions==food,"airborne roach cannot eat ground food");var enemy=new Bug{Id=2,Species=Species.Ant,P=b.P};w.Bugs.Add(enemy);double hp=b.Health;w.Combat(.6);check(b.Health==hp&&!b.Opponent.HasValue,"ground combat excludes airborne roach");
  var restored=Empty();restored.Restore(w.SaveJson());check(restored.Bugs.Select(x=>x.Id).SequenceEqual(w.Bugs.Select(x=>x.Id))&&restored.Bugs.All(x=>x.Flight==null),"save keeps colony and safely ends transient flights");w.Swat(b.P);check(!w.Bugs.Contains(b)&&w.Corpses.Any(x=>x.Id==1&&x.Flight==null)&&w.Splats.Count==1,"swatting a flying roach leaves a grounded corpse and juice");
  var land=Empty();var flyer=new Bug{Id=10,Species=Species.Roach,P=new V(600,450)};land.Bugs.Add(flyer);land.BeginFlight(flyer);for(int n=0;n<120;n++)land.Fly(flyer,.05);check(flyer.Flight==null&&flyer.Cooldown>0&&flyer.FlightWait>0,"flight lands and applies takeoff cooldown");
  var cap=Empty();for(int n=0;n<8;n++)cap.Bugs.Add(new Bug{Id=n,Species=Species.Roach,P=new V(200+n*100,400)});check(cap.ScareRoaches()==3&&cap.Bugs.Count(x=>x.Flight!=null)==3,"scare group capped at three flying roaches");check(cap.ScareRoaches()==0,"click spam cannot exceed flight budget");cap.Resize(1200,800);check(cap.Bugs.All(x=>x.Flight==null&&double.IsFinite(x.P.X)&&double.IsFinite(x.P.Y)),"display resize safely lands current flights");
  var natural=Empty();var scout=new Bug{Id=12,Species=Species.Roach,P=new V(500,400),FlightWait=0};natural.Bugs.Add(scout);natural.Update(.05);check(scout.Flight!=null,"unoccupied adult roach takes off naturally");var missed=Empty();missed.Bugs.Add(new Bug{Id=7,Species=Species.Roach,P=new V(700,400)});missed.Swat(new V(500,400));check(missed.Bugs[0].Flight!=null&&missed.Corpses.Count==0,"nearby missed slap triggers escape flight");check(Enum.GetValues<InvaderKind>().Length==5,"five foreign visitor species available");
  foreach(var kind in new[]{InvaderKind.Centipede,InvaderKind.Snake,InvaderKind.Rat}){var v=Empty();check(v.Summon(kind),"new foreign visitor enters: "+kind);var outsider=v.Invaders[0];for(int n=0;n<3;n++)v.Bugs.Add(new Bug{Id=n,Species=Species.Ant,P=outsider.P+new V(n*5,0),Health=100});outsider.Cooldown=0;if(kind==InvaderKind.Rat)v.AddFood(outsider.P,Snack.Pizza);int original=v.Foods.FirstOrDefault()?.Portions??0;v.SetRelation(Relation.Truce,"test");v.UpdateInvaders(.05);int hit=v.Bugs.Count(x=>x.Health<100);check(hit>0&&v.Relation==Relation.Truce&&outsider.Health<VisitorRules.Health(kind),"visitor damage and treaty-safe defense: "+kind);if(kind==InvaderKind.Centipede)check(hit==2&&outsider.Cooldown<1,"centipede rapidly bites two nearby targets");if(kind==InvaderKind.Snake)check(hit==1&&outsider.Cooldown==VisitorRules.Cadence(kind),"snake bites one target then recoils");if(kind==InvaderKind.Rat)check(outsider.Stolen==48&&v.Foods[0].Portions==original-48,"rat raid subtracts real snack portions");var reopen=Empty();reopen.Restore(v.SaveJson());check(reopen.Invaders[0].Kind==kind,"new visitor survives save restore: "+kind);outsider.Health=0;v.SweepAt(outsider.P);check(v.Invaders.Count==0,"new visitor remains can be swept away: "+kind);}
 }
}
